@verbatim<script>(function(){var T=(document.querySelector('meta[name=csrf-token]')||{}).content||'';
function post(url,body,cb){var f=new FormData();f.append('_token',T);for(var k in body)f.append(k,body[k]);fetch(url,{method:'POST',body:f,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest',Accept:'application/json'}}).then(function(r){return r.json().catch(function(){return{success:false,message:'Request failed ('+r.status+')'}})}).then(cb).catch(function(){cb({success:false,message:'Network error'})})}
var dn=document.getElementById('soDone');if(dn)dn.addEventListener('click',function(){if(dn.dataset.go!=='1'){dn.dataset.go='1';dn.textContent='Tap again to confirm';return}dn.disabled=true;post(location.pathname.replace(/\/$/,'')+'/return-complete',{},function(j){if(j.success)location.reload();else{dn.disabled=false;dn.dataset.go='';alert(j.message||'Failed')}})});
var rc=document.getElementById('soRcv'),ro=document.getElementById('soRcvOpen');if(rc&&ro){ro.addEventListener('click',function(){rc.style.display='flex';document.getElementById('soRErr').textContent=''});function rh(){rc.style.display='none'}document.getElementById('soRX').addEventListener('click',function(e){e.preventDefault();rh()});document.getElementById('soRCancel').addEventListener('click',rh);rc.addEventListener('mousedown',function(e){if(e.target===rc)rh()});
document.getElementById('soRSave').addEventListener('click',function(){var b=this,body={};rc.querySelectorAll('.soRc').forEach(function(w){body['back['+w.dataset.id+']']=w.querySelector('.soBk').value});b.disabled=true;post(location.pathname.replace(/\/$/,'')+'/return-receive',body,function(j){if(j.success)location.reload();else{b.disabled=false;document.getElementById('soRErr').textContent=j.message||'Failed'}})})}
var m=document.getElementById('soModal');if(!m)return;var op=document.getElementById('soOpen');
function paint(row){var q=+row.dataset.q,r=+row.querySelector('.soQ').value||0,bs=row.querySelectorAll('.soB');bs[0].style.background=r===0?'#16A34A':'#fff';bs[0].style.color=r===0?'#fff':'#334155';bs[1].style.background=r>0?'#C2410C':'#fff';bs[1].style.color=r>0?'#fff':'#334155'}
function calc(){var tot=0,ret=0;m.querySelectorAll('.soRow').forEach(function(w){var q=+w.dataset.q,i=w.querySelector('.soQ'),r=Math.max(0,Math.min(q,+i.value||0));if(+i.value!==r)i.value=r;tot+=q;ret+=r;paint(w)});var fin=0;m.querySelectorAll('.soRow').forEach(function(w){fin+=(+w.dataset.q-Math.max(0,Math.min(+w.dataset.q,+w.querySelector('.soQ').value||0)))*(+w.dataset.p||0)});var t,s;if(ret===0){t='All items received';s='Delivered'}else if(ret===tot){t='Full Return · '+ret+' of '+tot+' items return';s='Return Pending'}else{t='Partial Return · '+ret+' of '+tot+' items returning';s='Partial Return Pending'}document.getElementById('soRes').innerHTML='Result: <b>'+t+'</b><br>Status will become: <b>'+s+'</b>'+(ret>0&&ret<tot?'<br>Final delivered amount: <b>৳'+fin.toLocaleString()+'</b> (received items only)':'')}
m.querySelectorAll('.soRow').forEach(function(w){var i=w.querySelector('.soQ'),q=+w.dataset.q;w.querySelectorAll('.soB').forEach(function(b){b.addEventListener('click',function(){i.value=b.dataset.v==='1'?q:0;calc()})});i.addEventListener('input',calc)});
function show(){m.style.display='flex';document.getElementById('soErr').textContent='';calc()}function hide(){m.style.display='none'}
if(op)op.addEventListener('click',show);document.getElementById('soX').addEventListener('click',function(e){e.preventDefault();hide()});document.getElementById('soCancel').addEventListener('click',hide);m.addEventListener('mousedown',function(e){if(e.target===m)hide()});
document.getElementById('soSave').addEventListener('click',function(){var b=this,body={note:document.getElementById('soNote').value};m.querySelectorAll('.soRow').forEach(function(w){body['ret['+w.dataset.id+']']=w.querySelector('.soQ').value});b.disabled=true;post(location.pathname.replace(/\/$/,'')+'/outcome',body,function(j){if(j.success)location.reload();else{b.disabled=false;document.getElementById('soErr').textContent=j.message||'Failed'}})});
})();</script>@endverbatim
